text:
data/sales.csv lists sales: date, region, product, units, unit_price. Write report.py (Python 3, standard library only) that reads it and writes out/summary.json with:
- "revenue_by_region": region -> total revenue (units * unit_price) rounded to 2 decimals, regions lower-cased and stripped of spaces;
- "top_product": the product with the most units sold;
- "skipped_rows": how many rows were left out because units is empty or negative.
Run it so out/summary.json exists. Rows with empty or negative units are skipped and count nowhere else.

args.code:
import json, os

def check():
    path = "out/summary.json"
    if not os.path.exists(path):
        return "FAIL: out/summary.json missing"
    with open(path) as f:
        data = json.load(f)
    errs = []
    for key in ("revenue_by_region", "top_product", "skipped_rows"):
        if key not in data:
            errs.append(f"missing key {key}")
    if not errs:
        if not isinstance(data["revenue_by_region"], dict):
            errs.append("revenue_by_region not a dict")
        else:
            for k, v in data["revenue_by_region"].items():
                if not (isinstance(v, (int, float))):
                    errs.append(f"revenue value not numeric: {k}={v!r}")
                if k != k.strip().lower():
                    errs.append(f"region not lower/stripped: {k!r}")
        if not isinstance(data["top_product"], str):
            errs.append("top_product not str")
        if not isinstance(data["skipped_rows"], int):
            errs.append("skipped_rows not int")
    # cross-check against CSV
    import csv
    rev = {}
    units = {}
    skipped = 0
    with open("data/sales.csv", newline="") as f:
        for row in csv.DictReader(f):
            raw = (row.get("units") or "").strip()
            if raw == "":
                skipped += 1
                continue
            try:
                u = float(raw)
            except ValueError:
                skipped += 1
                continue
            if u < 0:
                skipped += 1
                continue
            up = float(row.get("unit_price") or 0)
            region = (row.get("region") or "").strip().lower()
            product = row.get("product") or ""
            rev[region] = rev.get(region, 0.0) + u * up
            units[product] = units.get(product, 0.0) + u
    expected_rev = {k: round(v, 2) for k, v in rev.items()}
    if data["revenue_by_region"] != expected_rev:
        errs.append(f"revenue mismatch: got {data['revenue_by_region']} want {expected_rev}")
    if data["skipped_rows"] != skipped:
        errs.append(f"skipped mismatch: got {data['skipped_rows']} want {skipped}")
    if units:
        top = max(units, key=lambda p: units[p])
        if data["top_product"] != top:
            errs.append(f"top_product mismatch: got {data['top_product']!r} want {top!r}")
    if errs:
        return "FAIL: " + "; ".join(errs)
    return "PASS"

